test("90 度回ったノードを運び、外接矩形の左辺が兄弟の左辺に近づいたら、外接矩形の左辺が揃う座標が書かれる", () => {
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupSiblings(90), onRepositionNode });
  drawnApart();
  drawnTurnedBadge();

  // 外接矩形を回る前の矩形として置くと、寄せ先がずれる
  dragNode("badge", { x: 103, y: -12 });

  expect(onRepositionNode).toHaveBeenCalledWith("badge", {
    parentName: "home",
    placement: { mode: "absolute", x: 146, y: 12 },
  });
});

test("90 度回ったノードを運んで兄弟の左辺へ吸い付いている間、隙間の数値は外接矩形の下辺から測られる", () => {
  renderCanvas({ selection: setupSiblings(90) });
  drawnApart();
  drawnTurnedBadge();

  // 上のテストと同じ量を運び、隙間は外接矩形で測る
  carryNode("badge", { x: 103, y: -12 });

  expect(snapGapLabels()).toEqual(["112"]);
});

test("倍率を上げても、90 度回ったノードは外接矩形の左辺が兄弟の左辺に揃う座標が書かれる", () => {
  /*
   * 1.2 倍では外接矩形の左辺が 152.8 + 125 = 277.8 に来て、`marker` の左辺 280 へ 2.2 寄る。
   * 運んだ量 127.2 を倍率で割り戻して x は 40 + 106。回る前の大きさに倍率を掛けないと
   * 外接矩形の左辺が 277 になって 3 寄り、x は 40 + 128 / 1.2 を丸めた 147 になる
   */
  const onRepositionNode = vi.fn();
  renderCanvas({ selection: setupSiblings(90), onRepositionNode });
  wheel(canvasSurface(), { x: 0, y: -100 }, "ctrl");
  drawnApartZoomed();

  dragNode("badge", { x: 125, y: -12 });

  expect(onRepositionNode).toHaveBeenCalledWith("badge", {
    parentName: "home",
    placement: { mode: "absolute", x: 146, y: 14 },
  });
});

test("90 度回した横長の矩形の外接矩形は、中心が同じ縦長の矩形になる", () => {
  const enclosing = RotatedBounds.toEnclosing({
    unrotated: Unrotated,
    rotation: 90,
  });

  expect(enclosing.left).toBeCloseTo(150);
  expect(enclosing.top).toBeCloseTo(0);
  expect(enclosing.width).toBeCloseTo(100);
  expect(enclosing.height).toBeCloseTo(200);
});

test("回っていなければ、端数を持つ矩形の外接矩形はその矩形そのもの", () => {
  expect(
    RotatedBounds.toEnclosing({
      unrotated: FractionalUnrotated,
      rotation: 0,
    }),
  ).toEqual(FractionalUnrotated);
});

test("360 度回した矩形の外接矩形は、回る前の矩形そのもの", () => {
  expect(
    RotatedBounds.toEnclosing({
      unrotated: FractionalUnrotated,
      rotation: 360,
    }),
  ).toEqual(FractionalUnrotated);
});

test("30 度回した矩形の外接矩形は、回った 4 角がちょうど収まる大きさになる", () => {
  // 幅 200·cos30 + 100·sin30、高さ 200·sin30 + 100·cos30 を、中心 (200, 100) に置いたもの
  const enclosing = RotatedBounds.toEnclosing({
    unrotated: Unrotated,
    rotation: 30,
  });

  expect(enclosing.left).toBeCloseTo(88.397, 3);
  expect(enclosing.top).toBeCloseTo(6.699, 3);
  expect(enclosing.width).toBeCloseTo(223.205, 3);
  expect(enclosing.height).toBeCloseTo(186.603, 3);
});

test("親の中の位置へ置き直すと、回る前の矩形の左上がその位置に来て大きさと向きは変わらない", () => {
  const placed = RotatedBounds.placedAt(
    { unrotated: Unrotated, rotation: 30 },
    { left: 10, top: 20, width: 400, height: 300 },
    { x: 5, y: 7 },
  );

  expect(placed).toEqual({
    unrotated: { left: 15, top: 27, width: 200, height: 100 },
    rotation: 30,
  });
});

test("30 度回したノードは、右辺を親の縁の近くまで引いても縁へ吸い付かない", () => {
  // 外接矩形の右辺が `home` の右の縁から閾値の内側に入る位置まで引くので、寄せる実装なら寄る
  const onResize = vi.fn();
  const tilted = Result.unwrap(
    DesignDocument.applyPropEdit(
      setupSelection().document,
      "turned",
      PropEdit.set(["rotation"], 30),
    ),
  );
  renderCanvas({
    selection: DocumentSelection.fromNames(tilted, ["turned"]),
    onResize,
  });
  drawnAt("home", { left: -78, top: -40, width: 360, height: 240 });
  const cos = Math.cos(Math.PI / 6);
  const sin = Math.sin(Math.PI / 6);
  const enclosingWidth = 200 * cos + 100 * sin;
  const enclosingHeight = 200 * sin + 100 * cos;
  const turned = drawnTurnedAt(
    "turned",
    {
      left: 150 - enclosingWidth / 2,
      top: 100 - enclosingHeight / 2,
      width: enclosingWidth,
      height: enclosingHeight,
    },
    { width: 200, height: 100 },
  );
  const rightEdge = { x: 150 + 100 * cos, y: 100 + 100 * sin };

  pressPointer(resizeHandleAt({ x: 1, y: 0.5 }), rightEdge);
  movePointer(turned, { x: rightEdge.x + 20 * cos, y: rightEdge.y + 20 * sin });

  const [width] = lastEdit(onResize).lengths;
  expect(width.axis).toBe("width");
  expect(width.length).toBeCloseTo(220);

/**
 * 回って描かれているノードとして描く。外接矩形を描かれた矩形にし、回る前の大きさを
 * レイアウトの大きさにする（外接矩形からは回る前の大きさが決まらないため）。
 *
 * @param name 描かれているノードの名前
 * @param enclosing 回った 4 角を囲む、描かれていることにする矩形
 * @param unrotatedSize 回る前の幅と高さ
 * @returns 測定を差し替えたあとの要素
 */
export function drawnTurnedAt(
  name: string,
  enclosing: CanvasBounds,
  unrotatedSize: Readonly<{ width: number; height: number }>,
): HTMLElement {
  const element = drawnAt(name, enclosing);
  stubLayoutSize(element, unrotatedSize);
  return element;
}

function snapAt(
  measured: RepositionMeasure,
  movedTo: Offset,
  targets: SnapTargets,
): SideSnapped {
  const moving = RotatedBounds.toEnclosing(
    RotatedBounds.placedAt(measured.dragged, measured.origin, movedTo),
  );
  return SideSnap.toSnapped(
    SideSnap.withSiblings(
      SideSnap.create(moving, targets.stationary),
      targets.siblings,
    ),
  );
}

/**
 * 回った 4 角を囲む軸に平行な矩形（外接矩形。画面には描かれない計算上の矩形）。
 *
 * @param bounds 回って描かれている矩形
 * @returns 回った 4 角をすべて含む最小の軸に平行な矩形。向きが 360 度の倍数（0 を含む）
 *   なら回る前の矩形そのもの
 */
toEnclosing(bounds: RotatedBounds): CanvasBounds {
  return enclosingCorners((ratio) => RotatedBounds.pointAt(bounds, ratio));
},

/**
 * 回る前の矩形の左上を、親の左上から見たその位置へ置き直す。大きさと向きは変わらない。
 *
 * @param bounds 置き直す矩形
 * @param parent 原点になる親の矩形
 * @param offset 親の左上から見た、回る前の矩形の左上の位置（画面上の px）
 * @returns 回る前の矩形をその位置へ置いた、同じ大きさ・同じ向きの矩形
 */
placedAt(
  bounds: RotatedBounds,
  parent: CanvasBounds,
  offset: Offset,
): RotatedBounds {
  return {
    unrotated: CanvasBounds.placedAt(parent, offset, bounds.unrotated),
    rotation: bounds.rotation,
  };
},
